int main(){auto gt=parseSourceCards(readFile("tests/fixtures/source2-listing.html"),2);auto lg=parseSourceCards(readFile("tests/fixtures/source3-listing.html"),3);assert(gt.size()>10&&lg.size()>10);assert(sourceLastPage(readFile("tests/fixtures/source2-listing.html"),2)==50);assert(sourceLastPage(readFile("tests/fixtures/source3-listing.html"),3)==173);for(auto&g:gt){assert(g.id>1000000000&&g.id<1500000000&&sourceForURL(g.image)==2);assert(g.image.find("data:")==std::string::npos);}for(auto&g:lg)assert(g.id>1500000000&&sourceForURL(g.url)==3&&!g.title.empty());auto a=torrentLinks(readFile("tests/fixtures/source2-detail.html"),2);auto b=torrentLinks(readFile("tests/fixtures/source3-detail.html"),3);assert(a.size()==1&&a[0].url.find(".torrent")!=std::string::npos);assert(b.size()==1&&b[0].url=="https://love-games1.net/load/0-0-0-22295-20");assert(torrentLinks("<a class='download_button_like_stat' data-gt-gated='1' href='/file.torrent'>Locked</a>",2).empty());assert(!sourceURL("https://gametorrent.org.evil/file"));assert(!sourceURL("https://love-games1.net@evil/file"));auto round=loadCatalog(serialize(lg));assert(round.size()==lg.size());auto base=loadCatalog(readFile("assets/catalog-source-1.tsv"));assert(!base.empty());assert(writeFile("build/provider-old-cache.tsv",serialize(base)));auto merged=mergedCatalog("assets/catalog.tsv","build/provider-old-cache.tsv");assert(merged.size()>base.size());remove("build/provider-old-cache.tsv");std::cout<<"Three-source URLs, listing parsers, pagination, stable IDs, download links and access-gate handling passed.\n";}
